// Normalise Gmail messages to the common email shape.
return $input.all().map(({ json: m }) => {
  const from = m.from?.value?.[0] || {};
  const text = m.text || String(m.html || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
  return { json: {
    source: 'Gmail',
    messageId: m.id || m.messageId || '',
    threadId: m.threadId || '',
    receivedAt: m.date ? new Date(m.date).toISOString() : new Date().toISOString(),
    fromName: from.name || '',
    fromEmail: (from.address || '').toLowerCase(),
    to: m.to?.text || '',
    subject: m.subject || '(no subject)',
    body: text,
    link: m.threadId ? `https://mail.google.com/mail/u/0/#all/${m.threadId}` : '',
    hasAttachments: Object.keys(m).some(k => k.startsWith('attachment')) || (m.attachments?.length > 0),
  } };
});

// Normalise Outlook (Microsoft Graph raw) messages to the common email shape.
return $input.all().map(({ json: m }) => {
  const from = m.from?.emailAddress || m.sender?.emailAddress || {};
  const html = m.body?.content || '';
  const text = m.body?.contentType === 'text' ? html :
    String(html).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n')
      .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/[ \t]+/g, ' ');
  return { json: {
    source: 'Outlook',
    messageId: m.id || '',
    threadId: m.conversationId || '',
    receivedAt: m.receivedDateTime || new Date().toISOString(),
    fromName: from.name || '',
    fromEmail: (from.address || '').toLowerCase(),
    to: (m.toRecipients || []).map(r => r.emailAddress?.address).join(', '),
    subject: m.subject || '(no subject)',
    body: text || m.bodyPreview || '',
    link: m.webLink || '',
    hasAttachments: !!m.hasAttachments,
  } };
});

// Pre-filter: drop internal / automated senders before spending AI tokens,
// strip quoted reply history and trim the body.
const e = $json;
const fromEmail = String(e.fromEmail || '').toLowerCase().trim();
const domain = fromEmail.split('@')[1] || '';
const list = v => String(v || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const internalDomains = list(e.internalDomains);
const ignorePatterns = list(e.ignoreSenderPatterns);

let skipReason = '';
if (!fromEmail) skipReason = 'No sender address';
else if (internalDomains.includes(domain)) skipReason = 'Internal sender (' + domain + ')';
else if (ignorePatterns.some(p => fromEmail.includes(p))) skipReason = 'Automated / no-reply sender';

// Remove quoted history ("On ... wrote:", "From: ... Sent:", lines starting with ">")
let body = String(e.body || '');
const cut = body.search(/\n(On .{0,200}wrote:|-{2,}\s*Original Message|From:\s.+\n(Sent|Date):)/i);
if (cut > 0) body = body.slice(0, cut);
body = body.split('\n').filter(l => !l.trim().startsWith('>')).join('\n')
  .replace(/\n{3,}/g, '\n\n').trim();
const max = Number(e.maxBodyChars) || 6000;
if (body.length > max) body = body.slice(0, max) + '\n...[truncated]';

return { json: { ...e, fromEmail, body, skipAI: !!skipReason, skipReason } };

