// Combine the original email with the AI classification.
const src = $('Filter and Prepare for AI').item.json;
const ai = $json.output || {};
const ok = !!ai.category;
return { json: {
  ...src,
  isCustomerRequest: ok ? !!ai.isCustomerRequest : false,
  category: ok ? ai.category : 'Unclassified',
  priority: ai.priority || 'Medium',
  confidence: typeof ai.confidence === 'number' ? ai.confidence : 0,
  productArea: ai.productArea || '',
  title: ai.title || src.subject || '(no subject)',
  summary: ai.summary || '',
  customerName: ai.customerName || src.fromName || '',
  customerCompany: ai.customerCompany || '',
  sentiment: ai.sentiment || 'Neutral',
  stepsToReproduce: ai.stepsToReproduce || '',
  reasoning: ai.reasoning || (ok ? '' : 'AI classification failed: ' + ($json.error?.message || $json.error || 'no output')),
  needsReview: !ok,
  classifiedBy: 'AI',
  classifiedAt: new Date().toISOString(),
} };

// Build the routing decision and Jira payload from Workflow Configuration.
const e = $json;
const ROUTES = {
  'Bug':             { issueType: e.bugIssueType || 'Bug',           assigneeAccountId: e.bugAssigneeAccountId,         slackChannel: e.bugSlackChannel,         labels: ['customer-email', 'bug'] },
  'Issue':           { issueType: e.issueIssueType || 'Task',        assigneeAccountId: e.issueAssigneeAccountId,       slackChannel: e.issueSlackChannel,       labels: ['customer-email', 'issue'] },
  'New Requirement': { issueType: e.requirementIssueType || 'Story', assigneeAccountId: e.requirementAssigneeAccountId, slackChannel: e.requirementSlackChannel, labels: ['customer-email', 'requirement'] },
};
// Optional: route specific product areas elsewhere, e.g. { billing: { slackChannel: 'billing' } }
const AREA_OVERRIDES = {};

let route = { ...(ROUTES[e.category] || ROUTES['Issue']) };
const area = String(e.productArea || '').toLowerCase();
for (const [key, ov] of Object.entries(AREA_OVERRIDES)) {
  if (area.includes(key)) { route = { ...route, ...ov }; break; }
}
route.slackChannel = String(route.slackChannel || '').replace('#', '');
route.owner = `${e.category} owner (#${route.slackChannel})`;

// Stable Jira label per email thread, used to find the open ticket for replies
const threadKey = String(e.threadId || e.messageId || e.subject || '');
let h = 5381;
for (let i = 0; i < threadKey.length; i++) h = ((h << 5) + h + threadKey.charCodeAt(i)) >>> 0;
const threadLabel = 'email-thread-' + h.toString(36);

const description = [
  `*Source:* customer email via ${e.source}`,
  `*From:* ${e.fromName || ''} <${e.fromEmail}>${e.customerCompany ? ' - ' + e.customerCompany : ''}`,
  `*Received:* ${e.receivedAt}`,
  `*Category / priority:* ${e.category} / ${e.priority} (AI confidence ${Math.round((e.confidence || 0) * 100)}%)`,
  `*Product area:* ${e.productArea || 'General'}  |  *Sentiment:* ${e.sentiment}`,
  '', 'h3. Summary', e.summary || '',
  e.stepsToReproduce ? '\nh3. Steps to reproduce\n' + e.stepsToReproduce : '',
  '', 'h3. Original email', `*Subject:* ${e.subject}`,
  '{noformat}', String(e.body || '').slice(0, 20000), '{noformat}',
].join('\n');

const PRIORITY_MAP = { Critical: 'Highest', High: 'High', Medium: 'Medium', Low: 'Low' };
const fields = {
  project: { key: e.jiraProjectKey },
  issuetype: { name: route.issueType },
  summary: String(e.title || e.subject || 'Customer request').slice(0, 250),
  description,
  labels: [...route.labels, threadLabel],
};
if (e.setJiraPriority && PRIORITY_MAP[e.priority]) fields.priority = { name: PRIORITY_MAP[e.priority] };
if (route.assigneeAccountId) fields.assignee = { accountId: route.assigneeAccountId };

return { json: {
  ...e,
  route,
  jiraBaseUrl: String(e.jiraBaseUrl || '').replace(/\/$/, ''),
  jiraPayload: { fields },
  threadLabel,
  dedupEnabled: e.dedupByThread !== false && !!threadKey,
  dedupJql: `labels = "${threadLabel}" AND statusCategory != Done ORDER BY created DESC`,
  followUpComment: [
    `Follow-up email from ${e.fromName || ''} <${e.fromEmail}> at ${e.receivedAt}`,
    `AI read: ${e.category} / ${e.priority} - ${e.summary || ''}`,
    '{noformat}', String(e.body || '').slice(0, 15000), '{noformat}',
  ].join('\n'),
} };

// Comment added to the open ticket: expose its key like a newly created issue.
const key = $('Search Open Jira Tickets').item.json.key || '';
return { json: { key: $json.error ? '' : key, isFollowUp: true, error: $json.error } };

// Build Slack and Teams messages from the Jira result.
const e = $('Build Jira Routing Decision').item.json;
const res = $json;
const jiraKey = res.key || '';
const isFollowUp = !!res.isFollowUp;
const jiraUrl = jiraKey ? `${e.jiraBaseUrl}/browse/${jiraKey}` : '';
const jiraError = jiraKey ? '' : String(res.error?.message || res.error || res.message || 'Jira issue not created');
const icon = { 'Bug': ':beetle:', 'Issue': ':warning:', 'New Requirement': ':bulb:' }[e.category] || ':envelope:';
const urgent = e.priority === 'Critical' && !isFollowUp ? '<!channel> ' : '';

const slackText = [
  isFollowUp ? `:speech_balloon: *Customer follow-up* on ${jiraKey} - ${e.category} / ${e.priority}`
             : `${urgent}${icon} *New customer ${e.category}* - *${e.priority}* priority`,
  `*${e.title}*`,
  `>${String(e.summary || '').replace(/\n/g, '\n>')}`,
  `*Customer:* ${e.customerName || e.fromName} <${e.fromEmail}>${e.customerCompany ? ' (' + e.customerCompany + ')' : ''}`,
  `*Area:* ${e.productArea || 'General'} | *Sentiment:* ${e.sentiment}`,
  jiraKey ? `*Jira:* <${jiraUrl}|${jiraKey}>` : `:x: *Jira not created:* ${jiraError.slice(0, 300)}`,
  e.link ? `<${e.link}|Open email>` : `_via ${e.source}_`,
].join('\n');

const teamsCard = {
  type: 'message',
  attachments: [{
    contentType: 'application/vnd.microsoft.card.adaptive',
    content: {
      $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4',
      body: [
        { type: 'TextBlock', size: 'Medium', weight: 'Bolder', wrap: true,
          text: isFollowUp ? `Customer follow-up on ${jiraKey}` : `New customer ${e.category} - ${e.priority}` },
        { type: 'TextBlock', wrap: true, weight: 'Bolder', text: e.title },
        { type: 'TextBlock', wrap: true, text: e.summary || '' },
        { type: 'FactSet', facts: [
          { title: 'Customer', value: `${e.customerName || e.fromName} <${e.fromEmail}>` },
          { title: 'Area', value: e.productArea || 'General' },
          { title: 'Jira', value: jiraKey || 'not created' },
        ] },
      ],
      actions: jiraUrl ? [{ type: 'Action.OpenUrl', title: 'Open in Jira', url: jiraUrl }] : [],
    },
  }],
};

return { json: { ...e, jiraKey, jiraUrl, jiraError, isFollowUp, slackText, teamsCard } };

// Result returned to the main pipeline.
const e = $('Create Notification Messages').item.json;
const slack = $('Send Slack Notification').item?.json || {};
const { jiraPayload, teamsCard, slackText, followUpComment, dedupJql, ...rest } = e;
return { json: {
  ...rest,
  assignedTo: e.route.owner,
  slackChannel: e.route.slackChannel,
  slackSent: !slack.error && (!!slack.ok || !!slack.message),
  teamsSent: !!e.teamsWebhookUrl,
  escalationStatus: !e.jiraKey ? 'Escalation failed - check Jira' : (e.isFollowUp ? 'Follow-up added to ' + e.jiraKey : 'Escalated'),
  escalatedAt: new Date().toISOString(),
} };

// Decide whether to acknowledge and build the reply text.
const e = $json;
const mode = String(e.ackMode || 'off').toLowerCase();   // off | draft | send
let skip = '';
if (!['draft', 'send'].includes(mode)) skip = 'Acknowledgement disabled';
else if (e.isFollowUp) skip = 'Follow-up on existing ticket';
else if (!e.jiraKey) skip = 'No ticket created';
else if (!e.messageId) skip = 'No message ID';

const RESPONSE_TIME = { Critical: '2 business hours', High: '1 business day', Medium: '2 business days', Low: '3 business days' };
const firstName = String(e.customerName || e.fromName || '').trim().split(/\s+/)[0] || 'there';
const what = { 'Bug': 'bug report', 'Issue': 'support request', 'New Requirement': 'feature request' }[e.category] || 'request';
const company = e.companyName || 'our team';

const ackText = [
  `Hi ${firstName},`,
  '',
  `Thank you for contacting ${company}. We have received your ${what} (reference: ${e.jiraKey}) and passed it to the right team.`,
  `You can expect an update within ${RESPONSE_TIME[e.priority] || '2 business days'}. Just reply to this email if you have anything to add.`,
  '',
  'Kind regards,',
  `${company} ${e.ackSignature || ''}`.trim(),
].join('\n');
const ackHtml = ackText.split('\n').map(l => `<p style="margin:0">${l || '&nbsp;'}</p>`).join('');

return { json: { ...e, ackMode: mode, ackSkipReason: skip, ackText, ackHtml,
  ackRoute: skip ? 'skip' : (e.source === 'Outlook' ? 'outlook' : (mode === 'send' ? 'gmail-send' : 'gmail-draft')) } };

// Return the email data plus acknowledgement status.
const e = $('Build Acknowledgement Reply').item.json;
let ackStatus;
if (e.ackSkipReason) ackStatus = 'Skipped: ' + e.ackSkipReason;
else if ($json.error) ackStatus = 'Failed: ' + ($json.error.message || $json.error);
else ackStatus = e.ackMode === 'draft' ? 'Draft created' : 'Sent';
const { ackText, ackHtml, ackRoute, ...rest } = e;
return { json: { ...rest, ackStatus } };

// Ask a human to triage emails the AI was not sure about.
const e = $json;
const reason = e.needsReview ? 'AI classification failed'
  : `Low confidence (${Math.round((e.confidence || 0) * 100)}% < ${Math.round((e.minConfidence || 0) * 100)}%)`;
const text = [
  `:mag: *Email needs manual triage* - ${reason}`,
  `*AI guess:* ${e.category} / ${e.priority}${e.productArea ? ' / ' + e.productArea : ''}`,
  `*From:* ${e.fromName || ''} <${e.fromEmail}>  |  *Subject:* ${e.subject}`,
  e.summary ? `>${String(e.summary).replace(/\n/g, '\n>')}` : '',
  e.reasoning ? `_Why:_ ${e.reasoning}` : '',
  e.link ? `<${e.link}|Open email>` : `_Source: ${e.source}_`,
].filter(Boolean).join('\n');
return { json: { ...e, reviewReason: reason, reviewText: text,
  reviewChannel: String(e.reviewSlackChannel || 'triage-review').replace('#', '') } };

// Return the email data plus review status.
const e = $('Alert for Email Review').item.json;
const { reviewText, ...rest } = e;
return { json: { ...rest, reviewAlertSent: !$json.error, escalationStatus: 'Sent to review (' + e.reviewReason + ')' } };

// Format a readable failure alert.
const ex = $json.execution || {};
const wf = $json.workflow || {};
const err = ex.error || {};
const text = [
  `:rotating_light: *Workflow failed:* ${wf.name || 'unknown'}`,
  `*Node:* ${ex.lastNodeExecuted || 'n/a'}  |  *Mode:* ${ex.mode || 'n/a'}`,
  `*Error:* ${String(err.message || 'Unknown error').slice(0, 500)}`,
  ex.url ? `<${ex.url}|Open execution>` : '',
].filter(Boolean).join('\n');
return [{ json: { text } }];
